['```c
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define a structure to represent a semaphore
typedef struct Semaphore {
    pthread_mutex_t mutex;
    int value;
} Semaphore;

// Function to create a new semaphore with an initial value
Semaphore* create_semaphore(const char* name, int initialValue) {
    Semaphore* semaphore = malloc(sizeof(Semaphore));
    if (semaphore == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for semaphore\n");
        exit(1);
    }

    // Initialize mutex and value
    pthread_mutex_init(&semaphore->mutex, NULL);
    semaphore->value = initialValue;

    return semaphore;
}

// Function to wait on a semaphore
void wait_semaphore(Semaphore* semaphore) {
    pthread_mutex_lock(&semaphore->mutex);
    while (semaphore->value == 0) {
        pthread_cond_wait(&semaphore->cond, &semaphore->mutex);
    }
    semaphore->value--;
    pthread_mutex_unlock(&semaphore->mutex);
}

// Function to signal a semaphore
void signal_semaphore(Semaphore* semaphore) {
    pthread_mutex_lock(&semaphore->mutex);
    semaphore->value++;
    pthread_cond_signal(&semaphore->cond);
    pthread_mutex_unlock(&semaphore->mutex);
}

// Function to destroy a semaphore
void destroy_semaphore(Semaphore* semaphore) {
    pthread_mutex_destroy(&semaphore->mutex);
    free(semaphore);
}


```




