#include <forward_list>
#include <string>

// ... Custom logging implementation ... //

void insertOrLogError(std::forward_list<std::string>& list, const std::string& target, const std::string& toInsert) {
  auto it = list.begin();
  while (it != list.end() && *it != target) {
    ++it;
  }

  if (it != list.end()) {
    list.insert_after(it, toInsert);
  } else {
    // Log insertion failure
    char buffer[256];
    snprintf(buffer, sizeof(buffer), "Failed to insert '%s' after '%s'. Target string not found in the list.", 
             toInsert.c_str(), target.c_str());
    logMessage(LogLevel::ERROR, buffer);
    list.push_back(toInsert); // Append if target not found
  }
}
```

