using System;
using System.Net.Http;
using System.Threading.Tasks;
using Microsoft.Extensions.Caching.Distributed;

public class HtmlUpdaterService
{
    private readonly HttpClient _httpClient;
    private readonly IDistributedCache _cache;
    private readonly string _apiEndpoint;
    private readonly int _cacheExpirationSeconds;

    public HtmlUpdaterService(HttpClient httpClient, IDistributedCache cache, string apiEndpoint, int cacheExpirationSeconds)
    {
        _httpClient = httpClient;
        _cache = cache;
        _apiEndpoint = apiEndpoint;
        _cacheExpirationSeconds = cacheExpirationSeconds;
    }

    public async Task<string> UpdateHtmlAsync(string url)
    {
        // Retrieve cached HTML content
        var cachedHtml = await _cache.GetAsync(url);

        if (cachedHtml != null)
        {
            return System.Text.Encoding.UTF8.GetString(cachedHtml); 
        }

        try
        {
            // Make API call for updated HTML content
            var response = await _httpClient.GetAsync(_apiEndpoint + url);

            if (response.IsSuccessStatusCode)
            {
                var htmlContent = await response.Content.ReadAsStringAsync();

                // Cache updated HTML content
                await _cache.SetAsync(url, System.Text.Encoding.UTF8.GetBytes(htmlContent), TimeSpan.FromSeconds(_cacheExpirationSeconds));

                return htmlContent;
            }
            else
            {
                throw new Exception($"API call failed with status code: {response.StatusCode}");
            }
        }
        catch (Exception ex)
        {
            // Log error and handle retry
            Console.WriteLine($"Error updating HTML for URL: {url}, Error: {ex.Message}");

            // Implement exponential backoff and retry logic
            throw; // Re-throw exception after retry 
        }
    }
}
```



