  footer.innerHTML = ''; // Clear existing content

  for (const script of scripts) {
    // Validate script data and create HTML elements dynamically
    // ...
    const scriptElement = document.createElement('div'); 
    scriptElement.textContent = script.name;
    footer.appendChild(scriptElement);
  }
}

async function updateFooter() {
  if (cache.has('scripts')) {
    renderFooter(cache.get('scripts'));
    return; // Use cached data for quick updates
  }

  const newScripts = await fetchScripts();
  cache.set('scripts', newScripts); // Cache fetched data
  renderFooter(newScripts); 
}

