            this.address = address;
            this.channel = channel;
        }

        @Override
        public void run() {
            try {
                // ... Handle incoming messages and process data asynchronously ...
            } catch (Exception e) {
                messagingSystem.notifyError(address, e);
                closeChannel();
            }
        }

        private void closeChannel() {
            // ... Close channel safely ...
        }
    }

    public void registerAddress(String address) throws IOException {
        Selector selector = selectors.computeIfAbsent(address, k -> {
            try {
                return Selector.open();
            } catch (IOException e) {
                throw new RuntimeException("Failed to open selector", e);
            }
        });

        SocketChannel channel = SocketChannel.open();
