// CommandExecutor.java

import java.io.BufferedReader;
import java.io.File;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.concurrent.TimeUnit;

public class CommandExecutor {

    private final String tempDir = System.getProperty("java.io.tmpdir"); 

    public void executeCommand(String command) throws IOException, InterruptedException {
        // Construct temporary output/error files
        File stdoutFile = new File(tempDir, "command_output.txt");
        File stderrFile = new File(tempDir, "command_error.txt");

        ProcessBuilder processBuilder = new ProcessBuilder("/bin/bash", "-c", command);
        processBuilder.redirectErrorStream(true)
                .redirectOutput(stdoutFile)
                .redirectError(stderrFile); 

        Process process = processBuilder.start();

        // Monitor command progress and handle timeout
        TimeUnit.SECONDS.sleep(10); // Adjust timeout as needed
        if (!process.waitFor(5, TimeUnit.SECONDS)) {
            // Handle timeout gracefully
            process.destroy();
        } 

        // Log output/error streams
        BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
        String line;
        while ((line = reader.readLine()) != null) {
            System.out.println("Stdout: " + line); // Replace with logging to file or database
        }

        reader = new BufferedReader(new InputStreamReader(process.getErrorStream()));
        while ((line = reader.readLine()) != null) {
            System.err.println("Stderr: " + line); // Replace with logging to file or database
        }

    }


}



// ... other utility classes for service interactions, retry logic, rate limiting ...
