    void processLogs(const std::string& logData) {
        std::lock_guard<std::mutex> lock(logQueueMutex);
        logQueue.push(logData);
        conditionVariable.notify_one();
    }

    void start() {
        for (int i = 0; i < threadPool.size(); ++i) {
            threadPool.emplace_back([this]() {
                while (running) {
                    std::unique_lock<std::mutex> lock(logQueueMutex);
                    conditionVariable.wait(lock, [this] { return !logQueue.empty() || !running; });

                    if (!running) break;

                    std::string logData = logQueue.front();
                    logQueue.pop();
                    lock.unlock();

                    // Process the log data here: parse format, apply filters, send to logging service

                }
            });
        }
    }

    void stop() {
        running = false;
        conditionVariable.notify_all();
        for (auto& thread : threadPool) {
            thread.join();
        }
    }

private:
    bool running; 
    ThreadPool threadPool;
    std::queue<std::string> logQueue;
    std::mutex logQueueMutex;
    std::condition_variable conditionVariable;
};



