    {
        return await GetCachedHtmlFromLocalCache(request); 
    }
    else
    {
        var htmlContent = await CallExternalApiAsync(request);

        // Cache Content with Rolling Window and Event-Based Invalidation
        await _distributedCache.SetAsync("html-content-" + request.Query["page"], htmlContent, new DistributedCacheEntryOptions 
        {
            AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(1), // Time-based invalidation
            SlidingExpiration = TimeSpan.FromSeconds(30) // Event-based invalidation (e.g., on API update)
        });

        return htmlContent;
    }

    // Fallback Mechanism for External API Errors 
