// C Function to Load Resource Bundle
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int loadResourceBundle(const char *filePath) {
    FILE *file = fopen(filePath, "r");
    if (file == NULL) {
        perror("Error opening file");
        return -1; // Error handling: Indicate file loading failure
    }

    char line[256];
    int count = 0;
    while (fgets(line, sizeof(line), file) != NULL) {
        count++;  // Increment counter for each item in the bundle
    }

    fclose(file);
    return count;
}
