) -> Result<(), Error> {
    let (tx, rx) = mpsc::channel(1024);

    // Spawn worker threads to process transactions asynchronously
    for _ in 0..num_workers {
        tokio::spawn(async move {
            while let Some(transactions) = rx.recv().await {
                process_batch(&transactions).await;
            }
        });
    }

    // Fetch transaction batches from API endpoint
    let mut last_request_time = chrono::Utc::now();
    loop {
        if chrono::Utc::now() - last_request_time > Duration::from_secs(rate_limit_strategy.interval()) {
