    workerThread.detach();
  }

  void addTelemetryData(const TelemetryData& data) {
    {
      std::lock_guard<std::mutex> lock(mutex_);
      dataQueue_.push(data);
    }
    cv_.notify_one(); 
  }

  void stopProcessing() {
    processingEnabled_ = false;
    cv_.notify_all();
  }
};



