// string_buffer.h

#ifndef STRING_BUFFER_H
#define STRING_BUFFER_H

typedef struct {
    char* buffer;
    size_t buffer_size;
    size_t current_position;
    pthread_mutex_t mutex;
} string_buffer_t;

int append_string_to_buffer(string_buffer_t* buffer, const char* str, size_t max_length);
void buffer_size_increment(string_buffer_t* buffer, size_t increment);

#endif 



// string_buffer.c

#include "string_buffer.h"

int append_string_to_buffer(string_buffer_t* buffer, const char* str, size_t max_length) {
    pthread_mutex_lock(&buffer->mutex);
    size_t str_length = strlen(str); 

    if (str_length > max_length || str_length + buffer->current_position > buffer->buffer_size) {
        pthread_mutex_unlock(&buffer->mutex);
        return -1; 
    }

    memcpy(buffer->buffer + buffer->current_position, str, str_length);
    buffer->current_position += str_length;
    pthread_mutex_unlock(&buffer->mutex);
    return buffer->current_position; 
}

void buffer_size_increment(string_buffer_t* buffer, size_t increment) {
    // Implement buffer resizing logic here
}



