    public TransactionProcessorService(PaymentGatewayManager gatewayManager, TransactionValidator validator, Logger logger) {
        this.gatewayManager = gatewayManager;
        this.validator = validator;
        this.logger = logger;
    }

    public Future<TransactionResult> processTransaction(TransactionRequest request) {
        return executorService.submit(() -> { 
            // Transaction Validation
            if (!validator.isValid(request)) {
                logger.error("Invalid transaction: {}", request);
                throw new TransactionException("Validation failed");
            }

            // Gateway Selection and Processing (async using gatewayManager)
            PaymentGateway gateway = gatewayManager.selectGateway(request);
            return gateway.processTransaction(request)
                    .exceptionally(throwable -> {
                        logger.error("Transaction error: {} ", throwable);
                        handleGatewayError(request, throwable); 
                        // Retry logic (Exponential backoff with limits)
                        return null; // Handle fallback or alternative processing
                    });
        });
    }

    private void handleGatewayError(TransactionRequest request, Throwable throwable) {
        // Implement error logging, retry mechanism, and potential fallback strategies
    }

}

