    // Acquire lock for thread safety
    pthread_mutex_lock(&sessionMutex); 

    // Allocate memory for the session
    Session* newSession = malloc(sizeof(Session));

    // Initialize session fields
    newSession->token = token; // Store user token
    newSession->timestamp = timestamp; // Record session start time
    newSession->refCount = 1; // Start with a reference count of 1
    newSession->logCallback = logCallback; // Set the logging callback

    // ... (Add logic to store session in storage, handle potential errors)

    // Release lock after operation is complete
    pthread_mutex_unlock(&sessionMutex); 
}


void destroySession(Session* session) {
    // Acquire lock for thread safety
    pthread_mutex_lock(&sessionMutex); 

    // Decrement reference count
    session->refCount--;
    if (session->refCount == 0) { // If no more references, deallocate the session
        free(session); 
    }

    // Release lock after operation is complete
    pthread_mutex_unlock(&sessionMutex);  
}



