async function encryptData(data, tenantId) {
  const options = { 
    hostname: 'your-encryption-service.com', 
    path: `/encrypt?tenantId=${tenantId}`,
    method: 'POST',
    headers: { 
      'Content-Type': 'application/json' 
    }
  };

  return new Promise((resolve, reject) => {
    const req = https.request(options, (response) => {
      let body = '';
      response.on('data', (chunk) => {
        body += chunk;
      });
      response.on('end', () => {
        try {
          resolve(JSON.parse(body)); // Parse encrypted data
        } catch (error) {
          reject(error); // Handle parsing errors
        }
      });
    });

    req.on('error', reject);
    req.write(JSON.stringify({ data })); 
    req.end();
  });
}
