import org.apache.kafka.clients.consumer.*;
import org.apache.spark.SparkConf;
import org.apache.spark.streaming.Durations;
import org.apache.spark.streaming.api.java.JavaDStream;
import org.apache.spark.streaming.api.java.JavaPairDStream;
import org.apache.spark.streaming.api.java.JavaStreamingContext;

public class RealTimeDataPlatform {

    public static void main(String[] args) {

        // 1. Kafka Consumer Configuration
        Properties props = new Properties();
        props.put("bootstrap.servers", "your_kafka_brokers");
        props.put("group.id", "real_time_data_group");
        props.put("key.deserializer", "org.apache.kafka.common.serialization.StringDeserializer");
        props.put("value.deserializer", "org.apache.kafka.common.serialization.StringDeserializer");

        KafkaConsumer<String, String> consumer = new KafkaConsumer<>(props);
        consumer.subscribe(Arrays.asList("your_topic_name"));

        // 2. Spark Streaming Configuration
        SparkConf conf = new SparkConf().setAppName("RealTimeDataPlatform");
        JavaStreamingContext jssc = new JavaStreamingContext(conf, Durations.seconds(2)); // Batch interval

        // 3. Data Ingestion from Kafka
        ConsumerRecords<String, String> records = consumer.poll(Duration.ofSeconds(1)); // Poll for messages
        for (var record : records) {
            System.out.println("Received message: " + record.value());
        }

        // 4. Spark Streaming Processing
        JavaDStream<String> kafkaData = jssc.sparkContext().textFileStream("path/to/data"); // Simulated data
        JavaPairDStream<String, Integer> wordCounts = kafkaData
                .flatMap(s -> Arrays.asList(s.split("\\s+")))
                .mapToPair(word -> new Tuple2<>(word, 1))
                .reduceByKey((a, b) -> a + b);

        // 5. Data Output/Storage (e.g., HDFS, Cassandra)
        wordCounts.print(); // Print results to console for demonstration

        jssc.start();
        jssc.awaitTermination();
    }
}


