int load_resource_bundle(const char* path, int* count) {
    std::ifstream file(path);
    if (!file.is_open()) {
        return -1; // Error opening file
    }

    std::string line;
    *count = 0;

    while (std::getline(file, line)) {
        (*count)++;
    }

    file.close();

    return 0; // Success
}
