public class GraphManager {
    private readonly Neo4jDriver _driver; // Initialize your Neo4j connection

    public GraphManager(Neo4jDriver driver) {
        _driver = driver;
    }

    public void CreateDynamicGraph(int numVertices, int edgeDensity) {
        using (var session = _driver.Session()) {
            for (int i = 0; i < numVertices; i++) {
                // Generate random properties for each vertex
                var properties = new Dictionary<string, object> {
                    {"name", $"Vertex {i}"},
                    {"value", Random.Shared.Next(100)},
                    // ... Add more random properties as needed
                };

                session.WriteTransaction(tx => {
                    tx.Create(NodeBuilder.Node("Vertex")
                        .WithProperties(properties));
                });
            }

            // Create edges between vertices based on edgeDensity
            for (int i = 0; i < numVertices - 1; i++) {
                for (int j = i + 1; j < numVertices; j++) {
                    var connectionProbability = Random.Shared.NextDouble(); // Simulate random connection

                    if (connectionProbability <= edgeDensity) {
                        session.WriteTransaction(tx => {
                            tx.Create(RelationshipBuilder.Create("CONNECTED")
                                .From("Vertex", i)
                                .To("Vertex", j));
                        });
                    }
                }
            }
        }
    }
}


```

