    public TextDataProcessor() {
        // Initialize Kafka Consumer
        Properties props = new Properties();
        props.put(ConsumerConfig.BOOTSTRAP_SERVERS_CONFIG, "localhost:9092"); // Kafka Broker address
        props.put(ConsumerConfig.GROUP_ID_CONFIG, "text-data-group");
        consumer = new KafkaConsumer<>(props);
        consumer.subscribe(Arrays.asList(KAFKA_TOPIC));

        // Initialize Firestore/MongoDB client
        firestoreDb = FirebaseOptions.builder() // Or MongoDB configuration
                .build()
                .getService(); 


        // ... (Initialize other dependencies)
    }

    public void run() {
        while (true) {
            ConsumerRecords<String, String> records = consumer.poll(Duration.ofMillis(100));
            for (ConsumerRecord<String, String> record : records) {
                try {
                    // Process text data
                    String textData = record.value();
                    // ... (Extract metadata, perform enrichment using external APIs, etc.)

                    DocumentReference docRef = firestoreDb.collection(FIREBASE_COLLECTION).document(); // Or MongoDB equivalent
                    docRef.set(textData); 

                    tracer.spanBuilder("process_text").start().end();
                } catch (Exception e) {
                    // Handle errors and implement retry logic with exponential backoff
                    System.err.println("Error processing text: " + e.getMessage());
                }
            }
        }
    }

    public static void main(String[] args) {
        TextDataProcessor processor = new TextDataProcessor();
        processor.run(); 
    }
}

