// Simplified example, actual implementation would be significantly more complex

#include <iostream>
#include <thread>
#include <mutex>
#include <queue>
#include <atomic>
#include <condition_variable>
#include <future>

enum LogLevel { DEBUG, INFO, WARN, ERROR, CRITICAL };

struct LogEntry {
    LogLevel level;
    std::string message;
    // ... Additional metadata fields like timestamp, request ID, etc.
};

class Logger {
public:
    void log(LogLevel level, const std::string& message) {
        LogEntry entry = {level, message};
        { 
            std::lock_guard<std::mutex> lock(logMutex);
            logQueue.push(entry);
        }
        loggerThreadCV.notify_one();
    }

private:
    void loggerThread() {
        while (true) {
            LogEntry entry;
            { 
                std::unique_lock<std::mutex> lock(logMutex);
                loggerThreadCV.wait(lock, [this] { return !logQueue.empty(); });
                entry = logQueue.front();
                logQueue.pop();
            }

            // ... Process the log entry (e.g., send to external service)
        }
    }

    std::mutex logMutex;
    std::condition_variable loggerThreadCV;
    std::queue<LogEntry> logQueue;
};

int main() {
    Logger logger;
    // ... Usage of the logger in different threads
    return 0;
}

```


