        self.data_sources: List[DataSource] = []
        self.schema_parser: SchemaParser = SchemaParser()
        self.processors: List[Callable[[Dict], Dict]] = []
        self.destination: Destination = Destination()

    def add_data_source(self, data_source: DataSource):
        self.data_sources.append(data_source)

    def add_processor(self, processor: Callable[[Dict], Dict]):
        self.processors.append(processor)

    def run(self):
        for data_source in self.data_sources:
            for batch in data_source.get_data():
                # Schema Parsing and Transformation
                parsed_batch = self.schema_parser.parse_batch(batch)

                # Data Processing Pipeline
                for processor in self.processors:
                    processed_batch = processor(parsed_batch)

                self.destination.write_data(processed_batch)


