void insertString(std::forward_list<std::string>& lst, const std::string& searchStr, const std::string& insertStr) {
    auto it = std::find(lst.begin(), lst.end(), searchStr);
    if (it != lst.end()) {
        lst.insert(it, insertStr);
    } else {
        lst.push_back(insertStr);
    }
}
