typedef struct {
    char *buffer;
    size_t buffer_size;
    size_t current_size;
    pthread_mutex_t mutex; 
} StringBuffer;

int append_string_to_buffer(StringBuffer *buffer, const char *input_string, size_t input_size, size_t max_append_size) {
    if (input_size > max_append_size || buffer->current_size + input_size >= buffer->buffer_size) {
        return -1; 
    }

    pthread_mutex_lock(&buffer->mutex); // Acquire mutex for thread safety

    memcpy(buffer->buffer + buffer->current_size, input_string, input_size); 
    buffer->current_size += input_size;
    buffer->buffer[buffer->current_size] = '\n';  // Append newline
    pthread_mutex_unlock(&buffer->mutex); // Release mutex

    return buffer->current_size;
}


void buffer_resize(StringBuffer *buffer, size_t new_size) {
    // ... Implementation for resizing the buffer safely 
    //  - Allocate a new buffer, copy existing data
    //  - Free the old buffer
    //  - Update buffer size and pointers
}

void *initialize_string_buffer(size_t initial_size) {
    StringBuffer *buffer = (StringBuffer *)malloc(sizeof(StringBuffer));
    if (buffer == NULL) {
        return NULL; // Handle allocation failure
    } 

    buffer->buffer = (char *)malloc(initial_size);
    if (buffer->buffer == NULL) {
        free(buffer);  // Release allocated memory
        return NULL; 
    }

    buffer->buffer_size = initial_size;
    buffer->current_size = 0;
    pthread_mutex_init(&buffer->mutex, NULL); // Initialize mutex

    return buffer;
}


void destroy_string_buffer(void *buffer_ptr) {
   // ... Implementation for freeing resources safely:
   //  - Free the allocated buffer memory
   //  - Destroy the mutex
   //  - Free the StringBuffer structure
} 



