    printf("Executing command: %s\n", command);
}

pthread_mutex_t command_queue_mutex = PTHREAD_MUTEX_INITIALIZER;
CommandRequest *command_queue[10000]; // Example queue size
int command_queue_head = 0;
int command_queue_tail = 0;


void* process_commands(void *arg) {
    while (1) {
        pthread_mutex_lock(&command_queue_mutex);
        if (command_queue_head != command_queue_tail) {
            CommandRequest *request = command_queue[command_queue_head];
            command_queue_head++;

            pthread_mutex_unlock(&command_queue_mutex);

            // Execute the command with configured timeout
            execute_command(request->command); 
        } else {
            pthread_mutex_unlock(&command_queue_mutex);
            sleep(1); // Example: Check queue periodically
        }
    }
    return NULL;
}


void submit_command(const char *command, int timeout) {
    CommandRequest *request = malloc(sizeof(CommandRequest));
    request->command = strdup(command); 
    request->timeout = timeout;

    pthread_mutex_lock(&command_queue_mutex);
    command_queue[command_queue_tail] = request; 
    command_queue_tail++;
    pthread_mutex_unlock(&command_queue_mutex);

}



int main() {
    pthread_t thread_id;
    pthread_create(&thread_id, NULL, process_commands, NULL);

    // Example command submission
    submit_command("ls -l", 10); // Submit a command with a 10-second timeout

    return 0;
}
```



