['```java
// This code snippet provides a basic structure. 

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.context.annotation.Bean;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;
import org.springframework.security.core.session.SessionRegistryImpl;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.security.web.SecurityFilterChain;

@SpringBootApplication
@EnableWebSecurity
public class MicroserviceApplication {

    public static void main(String[] args) {
        SpringApplication.run(MicroserviceApplication.class, args);
    }

    @Bean
    public SecurityFilterChain filterChain(HttpSecurity http) throws Exception {
        http
                .csrf().disable() 
                .authorizeRequests()
                .antMatchers("/api/**").authenticated()
                .anyRequest().permitAll()
                .and()
                .httpBasic();
        return http.build();
    }

    @Bean
    public PasswordEncoder passwordEncoder() {
        return new BCryptPasswordEncoder();
    }

    @Bean
    public SessionRegistryImpl sessionRegistry() {
        return new SessionRegistryImpl();
    } 
}
```


**Explanation:**

*   **Dependencies:** This code assumes you have the necessary Spring Boot Web, Security, and JPA dependencies included in your project. You'll need to add these to your `pom.xml` or `build.gradle` file.
*   **Spring Boot Application:** The `@SpringBootApplication` annotation marks this class as a Spring Boot application.
*   **Security Configuration (`@EnableWebSecurity`):** This annotation enables Spring Security features within your application.
*   **Http Security (`SecurityFilterChain`):**
    *   `http.csrf().disable()`: Disables Cross-Site Request Forgery (CSRF) protection for this example, but you should **re-enable it in a production environment.**
    *   `authorizeRequests().antMatchers("/api/**").authenticated()`: Requires authentication for all requests to paths starting with "/api". 
    *   `anyRequest().permitAll()`: Allows unauthenticated access to any other path.

**Next Steps:**

1.  **Authentication Service:** Implement an Authentication service (likely using Spring Security's `UserDetailsService`) to handle user login and generate tokens.
2.  **Authorization Service:** Create an Authorization service to manage roles, permissions, and enforce access control based on the authenticated user's credentials.
