#include <mutex>
#include <condition_variable>
#include <thread>

struct SemaphoreState {
  int initialValue;
  // ... other relevant data members ...
};

class Semaphore {
 public:
  Semaphore(const int& initialValue, const std::string& filePath) 
      : m_initialValue(initialValue), m_filePath(filePath) {}

  void acquire() { 
    std::unique_lock<std::mutex> lock(m_mutex);
    m_cv.wait(lock, [this] { return m_count > 0; });
    --m_count;
  }

  void release() {
    std::lock_guard<std::mutex> lock(m_mutex);
    ++m_count;
    m_cv.notify_one();
  }

 private:
  int m_count = 0;
  std::mutex m_mutex;
  std::condition_variable m_cv;
  int m_initialValue;
  std::string m_filePath;
};

