    if let Ok(path) = env::var("DIRECTORY_PATH") {
        println!("Directory path already exists: {}", path);
        return Ok(());
    }

    // 2. Directory service health check
    let directory_service = DirectoryService::new(); // ... instantiation

    // 3. Cache initialization
    let cache = Arc::new(Mutex::new(Cache::<String>::new()));

    // 4. Create directory and set environment variable
    if let Some(path) = createDirectory(&directory_service, &directory_name)? {
        env::set_var("DIRECTORY_PATH", path)?;

        // Update cache with newly created path
        cache.lock().unwrap().insert(directory_name, path);
    } else {
        return Err(String::from("Directory creation failed"));
    }

    Ok(())
}

