from flask import Flask, request, jsonify
import redis  # For caching

app = Flask(__name__)
redis_cache = redis.StrictRedis(host='localhost', port=6379, db=0)

class IDPHandler:
    def __init__(self, idp_type):
        self.idp_type = idp_type

    def authenticate(self, user_data):
        # Placeholder for IDP-specific authentication logic
        if self.idp_type == 'google':
            # Authenticate with Google API using user_data
            return {'token': 'google_access_token'} 
        elif self.idp_type == 'facebook':
            # Authenticate with Facebook API using user_data
            return {'token': 'facebook_access_token'}
        else:
            raise ValueError(f'Unsupported IDP type: {self.idp_type}')

@app.route('/login', methods=['POST'])
def login():
    user_data = request.get_json()
    idp_type = user_data.get('idp')
    handler = IDPHandler(idp_type)
    try:
        token = handler.authenticate(user_data)
        # Cache token using Redis for improved performance
        redis_cache.set(user_data['username'], token, ex=3600)  
        return jsonify({'message': 'Login successful', 'token': token})
    except ValueError as e:
        return jsonify({'error': str(e)}), 400

if __name__ == '__main__':
    app.run(debug=True) 
```

