#include <random>
#include <mutex>

template <typename T>
class DynamicValueGenerator {
public:
    struct RangeConfig {
        T minValue;
        T maxValue;
    };

    DynamicValueGenerator(const RangeConfig& initialRange = RangeConfig{0, 100}) :
        range{initialRange.minValue, initialRange.maxValue} {
        if (range.first >= range.second) {
            throw std::invalid_argument("minValue must be less than maxValue");
        }
    }

    void SetRange(const RangeConfig& newRange) {
        range = {newRange.minValue, newRange.maxValue};
        if (range.first >= range.second) {
            throw std::invalid_argument("minValue must be less than maxValue");
        }
    }

    T GenerateInclusive() {
        std::lock_guard<std::mutex> lock(m);
        return static_cast<T>(rand() % (range.second - range.first + 1)) + range.first;
    }

    T GenerateExclusive() {
        std::lock_guard<std::mutex> lock(m);
        return static_cast<T>(rand() % (range.second - range.first)) + range.first;
    }

    friend std::ostream& operator<<(std::ostream& os, const DynamicValueGenerator<T>& generator) {
        os << "Range: [" << generator.range.first << ", " << generator.range.second << "]";
        return os;
    }

private:
    RangeConfig range;
    std::mutex m;
};


```



