typedef struct {
  std::string key;
  std::string value;
} ResourceItem;

int load_resource_bundle(const char* filename, std::vector<ResourceItem>& bundle) {
  std::ifstream file(filename);
  if (!file.is_open()) {
    // Handle error: File not found or inaccessible
    return 1; // Error code
  }

  std::string line;
  while (std::getline(file, line)) {
    size_t separatorIndex = line.find('=');
    if (separatorIndex == std::string::npos) {
      // Handle error: Invalid format in resource file
      return 2; // Error code
    }

    ResourceItem item;
    item.key = line.substr(0, separatorIndex);
    item.value = line.substr(separatorIndex + 1);
    bundle.push_back(item);
  }

  file.close();
  return 0; // Success
}

int main() {
  std::vector<ResourceItem> bundle;
  int result = load_resource_bundle("resources.txt", bundle);
  if (result == 0) {
    std::cout << "Loaded " << bundle.size() << " items from resource file." << std::endl;
  } else if (result == 1) {
    std::cerr << "Error: Unable to open resource file." << std::endl;
  } else {
    std::cerr << "Error: Invalid resource file format." << std::endl;
  }

  return 0;
}
```



