  CommandData* cmd = (CommandData*)data;

  execute_command(cmd->config);
  log_command_status(cmd->command_id, 0); // Log completion status (0 for success)
  free(cmd);
  pthread_exit(NULL);
}

int main() {
  pthread_t threads[10000]; // Array to hold thread IDs
  CommandData* commands[10000]; // Array to store command data

  // Simulate receiving command requests
  for (int i = 0; i < 10000; ++i) {
    commands[i] = malloc(sizeof(CommandData));
    commands[i]->command_id = i;
    char* config = get_command_config(i);
    commands[i]->config = config;

    // Create a thread to handle each command
    pthread_create(&threads[i], NULL, handle_command, (void*)commands[i]);
  }

  // Wait for all threads to complete
  for (int i = 0; i < 10000; ++i) {
    pthread_join(threads[i], NULL);
  }

  return 0;
}
