        // Call third-party payment gateway API
        PaymentResponse paymentResponse = paymentGatewayClient.makePayment(request);

        // Handle payment response and update transaction status in cache
        TransactionStatus status = handlePaymentResponse(paymentResponse);
        transactionCache.updateTransactionStatus(transactionId, status);

        return ResponseEntity.status(HttpStatus.CREATED).body(new TransactionResponse(transactionId, status));
    }

    @GetMapping("/{transactionId}")
    @Cacheable("transactions")
    public ResponseEntity<TransactionResponse> getTransactionStatus(@PathVariable String transactionId) {
