import java.util.concurrent.TimeUnit;

// ... (Imports for logging service, external dependency management, etc.) 

public class DeserializationService {

    private final Map<String, Object> cache = new ConcurrentHashMap<>();
    private final int cacheSizeLimit;
    private final Logger logger;

    public DeserializationService(int cacheSizeLimit, Logger logger) {
        this.cacheSizeLimit = cacheSizeLimit;
        this.logger = logger;
    }

    public Object deserialize(byte[] data, String className) throws Exception {
        String key = generateKey(data);

        if (cache.containsKey(key)) {
            long startTime = System.nanoTime();
            Object deserializedObject = cache.get(key);
            logger.log(Level.INFO, "Cache hit for class: {}, key: {}", className, key);
            logger.log(Level.TRACE, "Deserialization time (ms): " + TimeUnit.NANOSECONDS.toMillis(System.nanoTime() - startTime));
            return deserializedObject;
        }

        try {
            long startTime = System.nanoTime();
            Object deserializedObject = deserializeData(data, className);
            cache.put(key, deserializedObject);
            cleanCache();
            logger.log(Level.INFO, "Deserialization successful for class: {}, key: {}", className, key);
            logger.log(Level.TRACE, "Deserialization time (ms): " + TimeUnit.NANOSECONDS.toMillis(System.nanoTime() - startTime));
            return deserializedObject;
        } catch (Exception e) {
            logger.log(Level.ERROR, "Deserialization failed for class: {}, key: {}. Error: {}", className, key, e.getMessage());
            throw e; 
        }
    }

    private void cleanCache() {
        // Implement cache cleaning logic based on size limit
    }

    private String generateKey(byte[] data) {
        // Implement key generation logic using hash or other suitable methods
    }

    private Object deserializeData(byte[] data, String className) throws Exception {
        Class<?> clazz = Class.forName(className);
        ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(data));
        return ois.readObject();
    }


}
