function updateClinicStatus($clinicId, $status, $ipAddress) {
    $region = getRegionFromIp($ipAddress); // Call external API with caching
    if (!authorizeUpdate($clinicId, $region)) {
        log_error("Unauthorized update attempt for clinic ID: $clinicId");
        return false;
    }

    $retryAttempts = 0;
    while (true) {
        try {
            // Database transaction to ensure atomicity
            $db->beginTransaction();

            $sql = "UPDATE clinics SET status = :status, last_modified_ip = :ipAddress, last_modified_date = NOW() WHERE id = :clinicId"; 
            $stmt = $db->prepare($sql);
            $stmt->execute([':status' => $status, ':ipAddress' => $ipAddress, ':clinicId' => $clinicId]);

            if ($stmt->rowCount() > 0) {
                log_success("Successfully updated clinic status for ID: $clinicId");
                $db->commit();
                break;
            } else {
                log_error("Failed to update clinic status for ID: $clinicId. No rows affected.");
                // Potential retry logic here based on database error type
            }
        } catch (PDOException $e) {
            log_error("Database error during update: " . $e->getMessage());
            $retryAttempts++;
            if ($retryAttempts >= MAX_RETRY_ATTEMPTS) {
                log_error("Max retries exceeded for clinic ID: $clinicId. Update failed.");
                notifyError(ERROR_CODE_DATABASE, "Clinic status update failed due to database errors.", $clinicId);
                break;
            } else {
                sleep(RETRY_DELAY); // Exponential backoff
                continue; 
            }
        } finally {
            $db = null; // Close connection after use
        }
    }

    // ... (Code to interact with audit log and notification services) ... 
    return true; 
}
```



