import json

class SensorReading:
    def __init__(self, temperature, humidity, pressure):
        self.temperature = temperature
        self.humidity = humidity
        self.pressure = pressure

def parse_sensor_data(json_string, target_class=SensorReading):
    try:
        data_dict = json.loads(json_string)
        temperature = data_dict.get("temperature")
        humidity = data_dict.get("humidity")
        pressure = data_dict.get("pressure")

        if not all([temperature, humidity, pressure]):
            raise ValueError("Required fields 'temperature', 'humidity', and 'pressure' are missing.")

        return target_class(temperature, humidity, pressure) 
    except json.JSONDecodeError:
        raise ValueError("Invalid JSON format in the input string.")
    except Exception as e:
        raise ValueError(f"Error parsing sensor data: {e}")   
