#include <forward_list>
#include <string>

void insertAfterFirstOccurrence(std::forward_list<std::string>& lst, const std::string& find, const std::string& insert) {
    auto before = lst.before_begin();
    for (auto it = lst.begin(); it != lst.end(); ++it) {
        if (*it == find) {
            lst.insert_after(before, insert);
            return; 
        }
        before = it;
    }
    lst.push_back(insert);  
}
