angular.module('myApp').service('dialogRefreshService', function($http, $q, logger) {
  var queue = [];
  var activeRequests = {};

  function refreshField(fieldConfig) {
    if (activeRequests[fieldConfig.name]) {
      return; 
    }
    activeRequests[fieldConfig.name] = true;
    $http({
      method: 'GET',
      url: fieldConfig.url,
    })
    .then(function(response) {
      // Process response and send to parent window
      window.parent.postMessage({ 
        fieldName: fieldConfig.name, 
        value: response.data 
      }, '*');
      delete activeRequests[fieldConfig.name];
    })
    .catch(function(error) {
      // Handle errors with logging and retries
      logger.error('Error refreshing field ' + fieldConfig.name, error);
      delete activeRequests[fieldConfig.name];
    });
  }

  this.refreshFields = function(resourceID, fields) {
    fields.forEach(function(fieldConfig){
      // ... logic to check for field matches and prioritize high-priority fields ...
      queue.push(fieldConfig);
    });

    // Process the queue asynchronously 
    this.processQueue();
  };

  this.processQueue = function() {
    if (queue.length > 0) {
      var nextField = queue.shift();
      refreshField(nextField);
    }
  };
});
