@RestController
public class TransactionProcessorService {

    @Autowired
    private Map<String, PaymentGateway> gateways;

    private final ExecutorService executor = Executors.newFixedThreadPool(10); // Adjust thread pool size based on load

    // Example endpoint for processing transactions
    @PostMapping("/process") 
    public HttpResponseStatus processTransaction(@RequestBody TransactionDetails details) {
        // Select the appropriate gateway based on transaction currency or other criteria
        PaymentGateway selectedGateway = gateways.getOrDefault(details.currency, new DefaultGateway()); // Use default gateway if no specific one found

        executor.execute(() -> { 
            HttpResponseStatus status = selectedGateway.processTransaction(details.amount, details.currency, details);
            // Handle response and potential errors (logging, retries, etc.)
        }); 

        return HttpResponseStatus.ACCEPTED; 
    }
}


