        {
            while (!reader.EndOfStream)
            {
                var transactionData = await reader.ReadLineAsync(); // Asynchronous line reading
                var transaction = TransactionParser.ParseTransaction(transactionData); // ...

                // Validation and Error Handling (consider async validation) 
