                // Asynchronous Payment Gateway Integration with Retry & Circuit Breaker Pattern
                var paymentResult = await _paymentGatewayClient.ProcessPaymentAsync(transaction);
                if (paymentResult.IsSuccess)
                {
                    await _transactionRepository.SaveTransactionAsync(transaction, paymentResult); // Database Ingestion
                }
                else
                {
                    // Handle payment gateway errors - retry/circuit breaker logic
                } 

            }
        }
    }
}




