class DataProcessor {
public:
  DataProcessor(int max_buffer_size) : buffer_size_(max_buffer_size), queue_() {}

  void process_data(const std::string& data) {
    std::unique_lock<std::mutex> lock(queue_mutex_);
    while (queue_.size() >= buffer_size_) { 
      // Handle backpressure: implement strategies like throttling or buffering
      std::cout << "Buffer full, dropping data.\n";
    }
    queue_.push(data);
    lock.unlock();

    // Process data asynchronously in a separate thread
    thread_pool_.enqueue([this]() { process_item(queue_.front()); queue_.pop(); }); 
  }

private:
  void process_item(const std::string& data) {
    // Perform analysis or processing on the received data
    std::cout << "Processing data: " << data << "\n";
  }

  int buffer_size_;
  std::queue<std::string> queue_;
  std::mutex queue_mutex_;
  ThreadPool thread_pool_; // Use a suitable thread pool implementation
};


int main() {
  DataProcessor processor(100); 

  // Simulate incoming data streams
  for (int i = 0; i < 200; ++i) {
    processor.process_data("Data " + std::to_string(i));
  }

  return 0;
}

