public class DataProcessingMicroservice {

    private final DataProcessor processor;
    private final MessageBroker broker;
    private final Logger logger = LoggerFactory.getLogger(DataProcessingMicroservice.class);

    @Autowired
    public DataProcessingMicroservice(DataProcessor processor, MessageBroker broker) {
        this.processor = processor;
        this.broker = broker;
    }

    @Bean
    public ScheduledExecutorService scheduledExecutor() {
        return Executors.newScheduledThreadPool(10);
    }

    @PostConstruct
    public void start() {
        logger.info("Data Processing Microservice started.");
    }

    @PreDestroy
    public void stop() {
        logger.info("Data Processing Microservice stopped.");
        // Log processing duration, errors, etc.
    }

    @Scheduled(fixedDelay = 60000) // Process data every minute
    public void processData() {
        try {
            List<DataRecord> records = processor.fetchDataFromSource();
            for (DataRecord record : records) {
                if (isValidData(record)) {
                    processor.processRecord(record);
                    broker.sendMessage(record); // Send status updates via message broker
                } else {
                    logger.warn("Invalid data record ignored: {}", record);
                }
            }
        } catch (Exception e) {
            logger.error("Error processing data: ", e);
            // Implement error handling and recovery
        }
    }

