        try {
            // Check if s3 is available (Implement Health check)
            if ($this->isS3Available()) {
                $result = $this->s3Upload($fileData, $fileName);
                return $result;
            } else {
                // Fallback to local storage
                $localResult = $this->localUpload($fileData, $fileName);
                return $localResult;
            }
        } catch (\Exception $e) {
            // Log the error and retry (implement exponential backoff)
            error_log("Upload Error: " . $e->getMessage());
            $attempts = 0;
            while ($attempts < 3) { // Example Retry Logic
                try {
                    if ($this->isS3Available()) {
                        return $this->s3Upload($fileData, $fileName); 
                    } else {
                        return $this->localUpload($fileData, $fileName);
                    }
                } catch (\Exception $e) {
                    error_log("Retry attempt " . $attempts . ": " . $e->getMessage());
                    sleep(pow(2, $attempts)); 
                    $attempts++;
                }
            }
            // If all retries fail, throw an exception
            throw new \Exception("Upload Failed after multiple attempts.");
        }
    }

