import queue
from threading import Thread
from time import sleep

class ImageConverterNode:
    def __init__(self):
        self.healthy = True  

    def convert_image(self, request):
        if self.healthy:
            try:
                # Simulate API call and conversion 
                sleep(request["size"] / 10) 
                return {"status": "success", "format": request["output_format"]}  
            except Exception as e:
                print(f"Conversion error on node: {e}")
                self.healthy = False
        else:
            return {"status": "failed", "reason": "Node offline"}

class LoadBalancer:
    def __init__(self, num_nodes=3):
        self.nodes = [ImageConverterNode() for _ in range(num_nodes)]
        self.queue = queue.Queue() 

    def add_request(self, request):
        self.queue.put(request)

    def distribute_request(self):
        healthy_nodes = [node for node in self.nodes if node.healthy] 
        if healthy_nodes:  
            # Simulate load balancing algorithm
            selected_node = healthy_nodes[0]  
            return selected_node.convert_image(request)
        else: 
            return {"status": "failed", "reason": "No healthy nodes available"}

class SystemManager:
    def __init__(self):
        self.load_balancer = LoadBalancer()
        # ... (Implementation for auto-scaling, caching, etc.)


if __name__ == "__main__":
    system = SystemManager() 
    while True:  
        # Simulate incoming requests
        request = {"input_format": "PNG", "output_format": "JPEG", "size": 1024}
        system.load_balancer.add_request(request)
        result = system.load_balancer.distribute_request()
