namespace HashingMicroservice
{
    public class HashService
    {
        private readonly IConfiguration _configuration;

        public HashService(IConfiguration configuration)
        {
            _configuration = configuration;
        }

        public async Task<string> GenerateHashAsync(string input)
        {
            using (SHA256 sha256 = SHA256.Create())
            {
                byte[] hashBytes = sha256.ComputeHash(Encoding.UTF8.GetBytes(input));
                return Convert.ToBase64String(hashBytes);
            }
        }

        public async Task<bool> VerifyHashAsync(string input, string storedHash)
        {
            string generatedHash = await GenerateHashAsync(input);
            return generatedHash == storedHash;
        }
    }
}
