        byte[] decryptionKey = awaitGetKeyFromKmsOrCache("decryptionKey");

        // 2. Generate nonce (should be obtained from ciphertext)
        byte[] nonce = ... // Extract nonce from ciphertext 

        // 3. Use AES-GCM to decrypt the ciphertext using key and nonce
        using (Aes aesAlg = Aes.Create())
