            aesAlg.Key = decryptionKey;
            aesAlg.Mode = CipherMode.GCM;
            aesAlg.Padding = PaddingMode.None;

            // ... (Code for decrypting the ciphertext using AES-GCM) ...
        }

        // ... (Handle successful decryption, log events, etc.) ...
    }

    private async Task<byte[]> getGetKeyFromKmsOrCache(string keyName)
    {
        if (_cachedKeys.TryGetValue(keyName, out byte[] cachedKey))
        {
            return cachedKey;
        }

        // Acquire semaphore to limit concurrent KMS calls
        await _encryptionSemaphore.WaitAsync(); 
        try
        {
            byte[] keyFromKms = await _keyManagementService.GetKeyAsync(keyName);
            _cachedKeys[keyName] = keyFromKms; 
            return keyFromKms;
        }
        finally
        {
            _encryptionSemaphore.Release();
        }
    }

}



