import java.util.*;
import java.util.concurrent.*;

public class MessageBroker {

    private final Map<String, List<MessageListener>> topicSubscribers = new HashMap<>();
    private final ExecutorService messageExecutor = Executors.newFixedThreadPool(10); // Adjust thread pool size as needed

    public void subscribe(String topic, MessageListener listener) {
        topicSubscribers.computeIfAbsent(topic, k -> new ArrayList<>()).add(listener);
    }

    public void publish(String topic, Message message) {
        messageExecutor.execute(() -> { 
            List<MessageListener> subscribers = topicSubscribers.get(topic);
            if (subscribers != null) {
                for (MessageListener listener : subscribers) {
                    listener.onMessage(message);
                }
            }
        });
    }

    public interface MessageListener {
        void onMessage(Message message);
    }

    public static class Message {
        private final String content;
        // Add other fields like sender, timestamp, etc. as needed

