pthread_mutex_t loggerMutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t loggerCond = PTHREAD_COND_INITIALIZER;
static struct LogMessage* logQueueHead = NULL;
static struct LogMessage* logQueueTail = NULL;
int logQueueSize = 0;

void log(LogLevel level, const char* format, ...) {
    // ... (Acquire mutex, allocate memory for log message)
    va_list args;
    va_start(args, format);
    vsnprintf(message->message, sizeof(message->message), format, args);
    va_end(args);

    message->level = level;
    // ... (Add timestamp, thread ID, etc.)

    pthread_mutex_lock(&loggerMutex);
    if (logQueueHead == NULL) {
        logQueueHead = message;
        logQueueTail = message;
    } else {
        logQueueTail->next = message;
        logQueueTail = message;
    }
    logQueueSize++;
    pthread_cond_signal(&loggerCond); 
    pthread_mutex_unlock(&loggerMutex);
}

void* loggingThread(void* arg) {
