const express = require('express');
const redis = require('redis');
const app = express();
const notificationService = require('./notificationService'); // Placeholder for your service

const client = redis.createClient();

app.post('/notifications', async (req, res) => {
  const message = req.body; // Assuming notification data is in the request body

  // 1. Use Redis semaphore for rate limiting and preventing race conditions
  client.acquire('notificationLock', 1, (err, acquired) => {
    if (err) throw err;
    if (!acquired) {
      return res.status(429).send('Rate limit exceeded'); // Handle exceeding the limit
    }

    // 2. Process notification based on message type and configuration
    notificationService.sendNotification(message);

    // 3. Release semaphore after processing is complete
    client.release('notificationLock');

    res.status(200).send('Notification sent successfully');
  });
});



module.exports = app;
