namespace RandomUtils {

class MersenneTwister {
 public:
  explicit MersenneTwister(std::seed_seq seed) : gen(seed) {}

  double operator()() { return gen(); }

 private:
  std::mt19937 gen;
};

class StreamManager {
 public:
  static MersenneTwister& createStream(int id) {
    std::lock_guard<std::mutex> lock(mutex_);
    auto it = streams_.find(id);
    if (it == streams_.end()) {
      it = streams_.emplace(id, MersenneTwister(seed_seq())).first;
    }
    return it->second;
  }

 private:
  static std::mutex mutex_;
  std::map<int, MersenneTwister> streams_;
