//  Payment Gateway Interface (abstract)
class PaymentGateway {
public:
    virtual ~PaymentGateway() {} 

    virtual bool processTransaction(const Transaction& transaction) = 0;
    virtual void refundTransaction(const Transaction& transaction) = 0;
};

// Concrete Payment Gateway Implementations
class CreditCardGateway : public PaymentGateway {
    // ... Implementation for credit card processing
};

class DigitalWalletGateway : public PaymentGateway {
    // ... Implementation for digital wallet processing
};

class CryptocurrencyGateway : public PaymentGateway {
    // ... Implementation for cryptocurrency processing
};

// Transaction Object
struct Transaction {
    // ... Properties: amount, currency, customer info, etc.
};


// Modular Payment Processor Component
class PaymentProcessor {
private:
    std::unique_ptr<PaymentGateway> gateway;
public:
    PaymentProcessor(const std::string& gatewayType) : gateway(createGateway(gatewayType)) {}

    bool processTransaction(const Transaction& transaction) {
        return gateway->processTransaction(transaction);
    }

    void refundTransaction(const Transaction& transaction) {
        gateway->refundTransaction(transaction);
    }

private:
    std::unique_ptr<PaymentGateway> createGateway(const std::string& type) {
        if (type == "CreditCard") { 
            return std::make_unique<CreditCardGateway>();
        } else if (type == "DigitalWallet") {
            return std::make_unique<DigitalWalletGateway>();
        } else if (type == "Cryptocurrency") {
            return std::make_unique<CryptocurrencyGateway>(); 
        } else {
            throw std::runtime_error("Invalid gateway type"); 
        }
    }

};

int main() {
    // ... Configuration and instantiation of PaymentProcessor
    PaymentProcessor processor("CreditCard"); // Example: Use Credit Card Gateway

    Transaction transaction; // Prepare transaction data

    if (processor.processTransaction(transaction)) {
        // Transaction successful
    } else {
        // Handle processing errors
    }

    return 0;
}
```



**Explanation:**

This code outlines the basic structure of a modular payment processing component in C++. It employs abstraction, polymorphism, and dependency injection to achieve flexibility and maintainability.


* **Abstraction:** The `PaymentGateway` interface defines common methods for processing transactions and refunds, abstracting away specific implementation details.
* **Polymorphism:** Concrete gateway implementations (e.g., `CreditCardGateway`) inherit from `PaymentGateway` and provide their own specialized transaction handling logic.
* **Dependency Injection:**  The `PaymentProcessor` component accepts the desired gateway type as a parameter during construction, allowing for easy switching between different payment methods.




