use std::env;
use std::fs;

fn create_directory_and_set_env(name: &str) {
    let dir = format!("{}/{}", env::var("HOME").unwrap_or_else(|_| "/home/user".to_string()), name);

    if !fs::metadata(&dir).is_ok() {
        fs::create_dir_all(&dir).unwrap();
        env::set_var(name, &dir);
    } else {
        let existing_path = env::var(name).unwrap_or_else(|_| String::new());
        if existing_path != dir {
            panic!("Conflicting directory paths found: {:?} and {:?}", existing_path, dir);
        }
    }
}
