const express = require('express');
const axios = require('axios');
const redis = require('redis');

const app = express();

const client = redis.createClient({
  host: 'localhost',
  port: 6379,
});

// Cache configuration
const cacheTTL = 60 * 60; // 1 hour

app.get('/footer', async (req, res) => {
  const scriptIds = req.query.scriptIds || [];

  // Fetch scripts from cache or API
  const cachedScripts = await client.hgetall(`scripts:${scriptIds.join(',')}`);

  if (cachedScripts && Object.keys(cachedScripts).length > 0) {
    res.send(cachedScripts);
    return;
  }

  try {
    const response = await axios.get('/api/scripts', { params: { scriptIds } });
    // Store scripts in cache
    client.hset(`scripts:${scriptIds.join(',')}`, Object.keys(response.data), response.data); 
    res.send(response.data);
  } catch (error) {
    console.error('Error fetching scripts:', error);
    res.status(500).send('Error loading footer components');
  }
});

app.listen(3000, () => console.log('Footer service listening on port 3000'));



