char* modify_file_extension(const char *filename) {

    char *original_ext = strrchr(filename, '.'); // Find the original extension

    if (original_ext == NULL) { 
        return NULL;  // Handle cases with no existing extension
    }

    int original_len = strlen(filename) - (original_ext - filename); 
    char *new_name = malloc(strlen(filename) + 10); // Allocate memory for new name
    if (new_name == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL; 
    }

    strncpy(new_name, filename, original_ext - filename);  // Copy the filename up to the extension
    sprintf(new_name + strlen(filename), ".%03d_%s", (int)(time(NULL)), "test"); 

    return new_name;

}



int main() {


   char *filename = "document.txt"; 
   char *modified_name = modify_file_extension(filename);
