// Helper function to find the largest integer in an array
int find_largest(int arr[], int size) {
  int largest = arr[0];
  for (int i = 1; i < size; i++) {
    if (arr[i] > largest) {
      largest = arr[i];
    }
  }
  return largest;
}

int main() {
  int n;
  printf("Enter the number of integers: ");
  scanf("%d", &n);

  int arr[n];
  printf("Enter the integers:\n");
  for (int i = 0; i < n; i++) {
    scanf("%d", &arr[i]);
  }

  int largest = find_largest(arr, n);
  printf("The largest integer is: %d\n", largest);

  return 0;
}
