use reqwest::Client;
use std::sync::{Arc, Mutex};

struct Config {
    base_url: String,
    timeout: u64,
    logging_level: String,
}

#[derive(Clone)]
pub struct HttpClient {
    client: Arc<Mutex<Client>>,
    config: Arc<Config>,
}

impl HttpClient {
    pub fn new(base_url: &str, timeout: u64, logging_level: &str) -> Self {
        let client = reqwest::Client::new();
        let config = Config {
            base_url: base_url.to_string(),
            timeout,
            logging_level: logging_level.to_string(),
        };

        Self {
            client: Arc::new(Mutex::new(client)),
            config: Arc::new(config),
        }
    }

    pub async fn make_request(&self, path: &str) -> Result<reqwest::Response, reqwest::Error> {
        let client = self.client.lock().unwrap();
        client.get(&format!("{}/{}", self.config.base_url, path))
            .timeout(std::time::Duration::from_secs(self.config.timeout))
            .send()
            .await
    }

    // ... (Implement other methods for dynamic updates, error handling, etc.)
}



``` 


