public class ModularLoggingFramework {

    private LogFormatter jsonFormatter = new JsonLogFormatter();
    private LogFormatter xmlFormatter = new XmlLogFormatter();
    private LogFormatter plainTextFormatter = new PlainTextLogFormatter();
    private LogLevel currentLogLevel = LogLevel.INFO; 

    public void setLogLevel(LogLevel level) {
        currentLogLevel = level;
    }

    public void logMessage(String message, LogType type) {
        if (type.getLevel().ordinal() >= currentLogLevel.ordinal()) {
            LogFormatter formatter = getFormatter(type);
            formatter.formatAndLog(message);
        }
    }

    private LogFormatter getFormatter(LogType type) {
        switch (type) {
            case JSON:
                return jsonFormatter;
            case XML:
                return xmlFormatter;
            case PLAIN_TEXT:
                return plainTextFormatter;
            default:
                throw new IllegalArgumentException("Invalid log type");
        }
    }

}



// Enums and classes for formatting, log levels, etc. 


