```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>


int main(int argc, char* argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <filename>\n", argv[0]);
        return 1;
    }

    FILE *fp = fopen(argv[1], "r");
    if (!fp) {
        perror("Error opening file");
        return 1;
    }

    char *line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, fp)) != -1) {
        // Process the line here
        char *token = strtok(line, ",");
        double sum = 0.0;
        int count = 0;

        while (token != NULL) {
            sum += atof(token);
            count++;
            token = strtok(NULL, ",");
        }

        // Calculate average of last two fields
        if (count >= 2) {
            double avg = sum / (count - 1);
            printf("%s,%f\n", line, avg); // Print in comma-separated format
        } else {
            fprintf(stderr, "Warning: Insufficient data in line: %s\n", line);
        }

    }

    free(line);
    fclose(fp);
    return 0;
}




