#include <pthread.h>

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// ... Other necessary headers and data structures ...

pthread_mutex_t crc_list_mutex; 
static NFAPI_CRC_INDICATION_PDU_T* crc_list = NULL;
static size_t crc_list_size = 0;
static size_t crc_list_capacity = 0;

void initialize_crc_list() {
    pthread_mutex_init(&crc_list_mutex, NULL);
}

void destroy_crc_list() {
    free(crc_list);
    pthread_mutex_destroy(&crc_list_mutex);
}

int add_crc_indication(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&crc_list_mutex);

    if (crc_list_size == crc_list_capacity) {
        // Resize the list if it's full
        crc_list_capacity *= 2; // Double the capacity
        crc_list = realloc(crc_list, crc_list_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!crc_list) {
            pthread_mutex_unlock(&crc_list_mutex);
            return -1; // Memory allocation failed
        }
    }

    crc_list[crc_list_size++] = *pdu;
    pthread_mutex_unlock(&crc_list_mutex);

    return 0;
}

// ... Other functions for accessing and managing the CRC list ...



```


