// Define the record structure
typedef struct {
  int key;
  long offset;
} Record;

// Global variables for the collection and mutex
Record *collection = NULL;
size_t capacity = 0;
size_t current_size = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize the collection with a given capacity
void initCollection(size_t initialCapacity) {
  capacity = initialCapacity;
  collection = (Record*)malloc(capacity * sizeof(Record));
  if (collection == NULL) {
    fprintf(stderr, "Memory allocation failed!\n");
    exit(1);
  }

  for (size_t i = 0; i < capacity; i++) {
    collection[i].key = rand(); // Generate random key
    collection[i].offset = collection[i].key * (long)rand(); // Calculate offset as a multiple of the key
  }
}

// Function to add a new record to the collection
void addRecord(int key, long offset) {
  pthread_mutex_lock(&mutex); 
  if (current_size == capacity) {
    // Resize if necessary
    resizeCollection(capacity * 2); // Example: Double the size
  }
  collection[current_size].key = key;
  collection[current_size].offset = offset;
  current_size++;
  pthread_mutex_unlock(&mutex);
}

// Function to resize the collection
void resizeCollection(size_t newCapacity) {
  Record *newCollection = (Record*)malloc(newCapacity * sizeof(Record));
  if (newCollection == NULL) {
    fprintf(stderr, "Memory allocation failed!\n");
    exit(1);
  }
  memcpy(newCollection, collection, capacity * sizeof(Record));
  free(collection);
  collection = newCollection;
  capacity = newCapacity; 
}

// Function to access a record by its key (for demonstration)
Record* getRecordByKey(int key) {
  pthread_mutex_lock(&mutex);
  for (size_t i = 0; i < current_size; i++) {
    if (collection[i].key == key) {
      pthread_mutex_unlock(&mutex);
      return &collection[i];
    }
  }
  pthread_mutex_unlock(&mutex);
  return NULL; // Key not found
}


int main() {
  // Seed the random number generator
  srand(time(NULL));

  initCollection(100); 

  addRecord(5, 12); // Example usage
  Record* foundRecord = getRecordByKey(5);

  if (foundRecord != NULL) {
    printf("Found record: key=%d, offset=%ld\n", foundRecord->key, foundRecord->offset);
  } else {
    printf("Record not found!\n");
  }

  return 0;
}
```



