using System.Data.SqlClient;
using System.Collections.Generic;

public class SqlHelper
{
    public static IDataReader ExecuteParameterizedCommand(string command, SqlConnection connection, List<object> parameters)
    {
        // Prepare the command with placeholders
        SqlCommand sqlCommand = new SqlCommand(command, connection);

        // Add parameters to the command object
        int i = 0;
        foreach (object param in parameters)
        {
            sqlCommand.Parameters.AddWithValue("@param" + i.ToString(), param);
            i++;
        }

        // Execute the command and return a DataReader for results
        return sqlCommand.ExecuteReader();
    }
}
```




