#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int count;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} Semaphore;

Semaphore* semaphore_create(int initial_count) {
    Semaphore* sem = (Semaphore*)malloc(sizeof(Semaphore));
    sem->count = initial_count;
    pthread_mutex_init(&sem->mutex, NULL);
    pthread_cond_init(&sem->cond, NULL);
    return sem;
}

void semaphore_wait(Semaphore* sem) {
    pthread_mutex_lock(&sem->mutex);
    while (sem->count == 0) {
        pthread_cond_wait(&sem->cond, &sem->mutex);
    }
    sem->count--;
    pthread_mutex_unlock(&sem->mutex);
}

void semaphore_post(Semaphore* sem) {
    pthread_mutex_lock(&sem->mutex);
    sem->count++;
    pthread_cond_signal(&sem->cond);
    pthread_mutex_unlock(&sem->mutex);
}


// ... (Additional functions for resource pooling, logging, 
// monitoring, error handling, extensibility)

int main() {
    // ... (Usage examples demonstrating semaphore operations)
    return 0;
}
```



**Remember:** This is a highly simplified representation. Building a production-ready semaphore library with all the features mentioned would require significantly more code and attention to detail regarding thread safety, memory management, error handling, logging, and performance optimization.']

