import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class MD5HashService {

    private final ExecutorService executor = Executors.newFixedThreadPool(10); // Configure thread pool size
    private final DistributedCache cache = new RedisDistributedCache(); // Use your existing cache solution

    public void processString(String input) {
        executor.execute(() -> {
            try {
                String hash = computeMD5(input);
                cache.put(hash, input); // Cache the MD5 hash and original string 
            } catch (NoSuchAlgorithmException e) {
                // Handle exception, log error details with input string
            }
        });
    }

    private String computeMD5(String input) throws NoSuchAlgorithmException {
        MessageDigest md = MessageDigest.getInstance("MD5");
        md.update(input.getBytes()); 
        byte[] hashBytes = md.digest();
        return bytesToHex(hashBytes); // Convert byte array to hexadecimal string representation
    }

    private String bytesToHex(byte[] hashBytes) {
        // Implementation for converting byte array to hexadecimal string
    }

    public void shutdown() {
        executor.shutdown();
        try {
            executor.awaitTermination(1, TimeUnit.MINUTES); // Graceful shutdown with timeout
        } catch (InterruptedException e) {
            // Handle interruption
        }
    }
}


