import org.apache.kafka.clients.consumer.ConsumerConfig;
import org.apache.kafka.common.serialization.StringDeserializer;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.kafka.config.ConcurrentKafkaListenerContainerFactory;
import org.springframework.kafka.core.ConsumerFactory;
import org.springframework.kafka.core.DefaultKafkaConsumerFactory;
import org.springframework.kafka.listener.ConcurrentMessageListenerContainer;

import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

@Configuration
public class MD5MicroserviceConfig {

    @Value("${spring.kafka.bootstrap-servers}")
    private String bootstrapServers;

    @Value("${spring.kafka.consumer.group-id}")
    private String groupId;

    @Bean
    public ConsumerFactory<String, String> consumerFactory() {
        return new DefaultKafkaConsumerFactory<>(consumerConfig());
    }

    @Bean
    public ConcurrentKafkaListenerContainerFactory<String, String> kafkaListenerContainerFactory() {
        ConcurrentKafkaListenerContainerFactory<String, String> factory = 
                new ConcurrentKafkaListenerContainerFactory<>();
        factory.setConsumerFactory(consumerFactory());
        return factory;
    }

    private Map<String, Object> consumerConfig() {
        Map<String, Object> props = new HashMap<>();
        props.put(ConsumerConfig.BOOTSTRAP_SERVERS_CONFIG, bootstrapServers);
        props.put(ConsumerConfig.GROUP_ID_CONFIG, groupId);
        props.put(ConsumerConfig.KEY_DESERIALIZER_CLASS_CONFIG, StringDeserializer.class);
        props.put(ConsumerConfig.VALUE_DESERIALIZER_CLASS_CONFIG, StringDeserializer.class);
        return props;
    }

    @Bean
    public MD5HashCalculator md5HashCalculator() {
        return new MD5HashCalculator();
    }

    // ... Cache implementation (e.g., Redis, Caffeine)

}


class MD5HashCalculator {

    private final DistributedCache cache;

    public MD5HashCalculator(DistributedCache cache) {
        this.cache = cache;
    }

    public String calculateAndStoreMD5Hash(String input) {
        // 1. Check if hash exists in cache
        if (cache.containsKey(input)) {
            return cache.get(input);
        }

        // 2. Calculate MD5 hash
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] messageDigest = md.digest(input.getBytes());
            String hash = String.format("%032x", new BigInteger(1, messageDigest));

            // 3. Store hash in cache
            cache.put(input, hash);

            return hash;
        } catch (NoSuchAlgorithmException e) {
            // Handle exception appropriately (logging, retry, etc.)
            throw new RuntimeException("Failed to calculate MD5 hash", e);
        }
    }
}



```


