class InventoryManager {
 public:
  // Add a new ProductInventory record
  void addProduct(const ProductInventory& product) {
    std::unique_lock<std::mutex> lock(inventoryMutex);
    inventory.push_back(product);
  }

  // Update an existing ProductInventory record by productID
  void updateProduct(int productID, const ProductInventory& updatedProduct) {
    std::unique_lock<std::mutex> lock(inventoryMutex);
    auto it = std::find_if(inventory.begin(), inventory.end(), 
                          [&productID](const ProductInventory& p) {
                            return p.productID == productID;
                          });

    if (it != inventory.end()) {
      *it = updatedProduct;
    } else {
      // Handle case where product not found
    }
  }

  // Retrieve a ProductInventory record by productID
  ProductInventory getInventory(int productID) const {
    std::unique_lock<std::mutex> lock(inventoryMutex);
    auto it = std::find_if(inventory.begin(), inventory.end(), 
                          [&productID](const ProductInventory& p) {
                            return p.productID == productID;
                          });

    if (it != inventory.end()) {
      return *it;
    } else {
      // Handle case where product not found
    }
  }

  // Clear all inventory records
  void clearInventory() {
    std::lock_guard<std::mutex> lock(inventoryMutex);
    inventory.clear();
  }

 private:
