using namespace std;

// Data structure for sensor readings
struct SensorReading {
  int deviceId;
  double value;
  chrono::system_clock::time_point timestamp;
};

// Global queue for sensor readings
queue<SensorReading> dataQueue;
mutex queueMutex;
condition_variable dataAvailable;

// Function to simulate receiving sensor data from an IoT device
void receiveData(int deviceId) {
  while (true) {
    // Simulate data generation and compression
    double value = rand() % 100; // Example: generate random value

    SensorReading reading = {deviceId, value, chrono::system_clock::now()};

    // Acquire lock to access queue
    unique_lock<mutex> lock(queueMutex);

    // Add data to the queue
    dataQueue.push(reading);

    // Notify waiting threads about new data
    dataAvailable.notify_one();

    // Sleep for a short duration (simulate real-time sensor reading)
    this_thread::sleep_for(chrono::milliseconds(10)); 
  }
}

// Function to process sensor readings from the queue
void processData() {
  while (true) {
    // Acquire lock to access queue
    unique_lock<mutex> lock(queueMutex);

    // Wait for new data if the queue is empty
    dataAvailable.wait(lock, [] { return !dataQueue.empty(); });

    // Retrieve data from the queue
    SensorReading reading = dataQueue.front();
    dataQueue.pop();

    // Process sensor reading (example: send to cloud analytics platform)
    cout << "Processed reading: DeviceID=" << reading.deviceId << ", Value=" << reading.value << endl;

    lock.unlock();
  }
}

int main() {
  // Initialize threads for receiving and processing data
  vector<thread> receiveThreads;
  for (int i = 0; i < 100; ++i) {
    receiveThreads.push_back(thread(receiveData, i)); 
  }

  // Start processing thread
  thread processThread(processData);


  // Wait for threads to complete
  for (auto& thread : receiveThreads) {
    thread.join();
  }
  processThread.join();

  return 0;
}
