function extractOldTestamentBooks(text) {
  const bookCounts = {};
  const textLower = text.toLowerCase(); 

  for (const regex of [bookRegex]) {
    const matches = textLower.match(regex);
    if (matches) {
      for (const match of matches) {
        bookCounts[match] = (bookCounts[match] || 0) + 1;
      }
    }
  }

  return bookCounts;
}
