// This code snippet provides a skeletal framework for the C library.

#include <stdlib.h>
#include <pthread.h>
#include <string.h> 

typedef struct {
    void* data;   
    size_t size;
} StateEntry;


typedef struct {
    StateEntry* entries;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex; 
} StateList;

StateList* createStateList() {
    StateList* list = (StateList*)malloc(sizeof(StateList));
    list->entries = NULL;
    list->capacity = 0;
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void addStateToList(StateList* list, void* data, size_t size) {
    pthread_mutex_lock(&list->mutex);
    if (list->count == list->capacity) {
        // Resize the list if full
        list->capacity *= 2;
        list->entries = (StateEntry*)realloc(list->entries, list->capacity * sizeof(StateEntry));
    }

    list->entries[list->count].data = data;
    list->entries[list->count].size = size;
    list->count++;

    pthread_mutex_unlock(&list->mutex);
}

// ... (Implement other functions like removeState, getStateByIndex, etc.)



``` 


