async fn batchProcessImages(bucket_name: &str, batch_size: usize) -> Result<(), Error> {
    let client = Client::new("redis://localhost:6379").connect().await?;
    let (tx, rx) = mpsc::channel(1024);

    // Spawn worker tasks
    for _ in 0..8 { // Adjust number of workers based on CPU cores
        tokio::spawn(async move {
            loop {
                if let Some(image_info) = rx.recv().await {
                    process_image(&client, &image_info).await;
                } else {
                    break; 
                }
            }
        });
    }

    // Iterate over images in S3 bucket
    for i in 0.. { // Use pagination for large buckets
        let image_infos = get_images_from_s3(bucket_name, i * batch_size, batch_size).await?;
        tx.send_all(&image_infos).await;
    }

    // Wait for workers to complete processing
    for _ in 0..8 { // Adjust based on worker count
        rx.recv().await; 
    }

    Ok(())
}


