 * JavaScript function for asynchronous reduction of an array of numbers.
 */
(async (numbers) => {
  return new Promise((resolve, reject) => {
    const reducer = (accumulator, currentValue) => accumulator + currentValue;
    numbers.reduce(reducer, 0).then(result => {
      resolve(result);
    }).catch(error => {
      reject(error);
    });
  });
})();

