    @PostMapping("/upload")
    public ResponseEntity<UploadResponse> uploadFile(@RequestParam("file") MultipartFile file, 
                                                     @RequestHeader("Metadata") String metadata) {
        // Validate and sanitize metadata
        try {
            String storageKey = storageService.uploadFile(file); 
            metricsCollector.recordUploadLatency(); // Track latency
            return ResponseEntity.ok(new UploadResponse(storageKey)); 
        } catch (Exception e) {
            // Log detailed error, implement exponential backoff retry logic
            metricsCollector.recordUploadError(); // Track error rate
            throw new RuntimeException("Upload failed", e);
        }
    }

