    public ResponseEntity<byte[]> downloadFile(@PathVariable String key) {
        try {
            byte[] fileData = storageService.downloadFile(key);
            metricsCollector.recordDownloadLatency(); // Track latency
            return ResponseEntity.ok().body(fileData);
        } catch (Exception e) {
            // Log detailed error, implement exponential backoff retry logic
            metricsCollector.recordDownloadError(); // Track error rate
            throw new RuntimeException("Download failed", e);
