// DynamicValueGenerator.h
#ifndef DYNAMIC_VALUE_GENERATOR_H
#define DYNAMIC_VALUE_GENERATOR_H

template <typename T>
class DynamicValueGenerator {
public:
    DynamicValueGenerator(T min = T(), T max = T()) : min_(min), max_(max) {}
    void SetRange(T min, T max) { 
        std::lock_guard<std::mutex> lock(mutex_); 
        min_ = min;
        max_ = max; 
    }

    T Generate() {
        std::lock_guard<std::mutex> lock(mutex_); 
        return static_cast<T>(rand() % (static_cast<int>(max_) - static_cast<int>(min_)) + static_cast<int>(min_));
    }

    std::string ToString() const {
        return "Min: " + std::to_string(min_) + ", Max: " + std::to_string(max_);
    }
private:
    T min_;
    T max_;
    std::mutex mutex_; 
};

#endif



```

**Explanation:**

- **CDNAssetManager.h:** This header file defines the basic structure of the `CDNAssetManager` class, which will handle all core functionality related to managing media assets in the CDN.

- **DynamicValueGenerator.h:** This header file defines a generic `DynamicValueGenerator` template class that can generate random values within a configurable range.
    -  **Template Parameter:** The `<T>` parameter allows the generator to work with different data types (e.g., integers, floats).
    - **Constructor:** Initializes the minimum and maximum values for the range. 
    - **SetRange():** Updates the minimum and maximum values of the range. It uses a mutex (`std::mutex`) to ensure thread safety when modifying the range in a multi-threaded environment. 
