  std::ifstream file(filePath);
  if (!file.is_open()) {
    return FILE_OPEN_ERROR;
  }

  // Determine the number of items in the bundle (e.g., by counting lines)
  int itemCount = 0;
  std::string line;
  while (std::getline(file, line)) {
    itemCount++;
  }

  // Allocate memory for the bundle and its items
  *bundle = new ResourceBundleItem[itemCount];
  if (!*bundle) {
    return MEMORY_ALLOC_ERROR;
  }

  // Reset file pointer to beginning
  file.clear();
  file.seekg(0);

