// C program to parse command line arguments and print usage information/line count

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char *argv[]) {
    if (argc == 1) {
        printf("Usage: %s [-m] [-cs] [-o output_file] input_file\n", argv[0]);
        return 1;
    }

    FILE *fp = fopen(argv[argc - 1], "r");
    if (fp == NULL) {
        perror("fopen");
        return 1;
    }

    int lineCount = 0;
    char line[1024];
    while (fgets(line, sizeof(line), fp) != NULL) {
        lineCount++;
    }
    fclose(fp);

    printf("Number of lines: %d\n", lineCount);
    return 0;
}
