std::vector<struct StreamData> generateStreamData(int numStreams) {
  std::vector<StreamData> streamData;

  for (int i = 0; i < numStreams; ++i) {
    StreamData data;
    data.timestamps = new unsigned long[10]; // Allocate memory for timestamps
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> distrib(1, 1000);

    for (int j = 0; j < 10; ++j) {
      data.timestamps[j] = distrib(gen);
    }

    data.channelID = "Channel_" + std::to_string(i);
    data.segmentDurations = new std::vector<int>(5); // Allocate memory for durations

    for (int j = 0; j < 5; ++j) {
      data.segmentDurations->push_back(distrib(gen));
    }

    streamData.push_back(data);
  }

  return streamData;
}

struct StreamData {
  unsigned long* timestamps;
  std::string channelID;
  std::vector<int>* segmentDurations;
}; 



int main() {
