class CommandExecutor {
private:
    std::queue<std::string> commandQueue;
    std::mutex queueMutex;
    std::condition_variable cv;

public:
    void executeCommand(const std::string& command) {
        { 
            std::lock_guard<std::mutex> lock(queueMutex);
            commandQueue.push(command); 
        }
        cv.notify_one();
    }

    void processCommands() {
        while (true) {
            std::string command;
            { 
                std::unique_lock<std::mutex> lock(queueMutex);
                cv.wait(lock, [this](){ return !commandQueue.empty(); }); // Wait for a command
                command = commandQueue.front();
                commandQueue.pop();
            }

            // Process the command asynchronously
            std::future<bool> result = std::async([command]() {
                // Simulate command execution with potential errors
                int randomValue = rand() % 10;
                if (randomValue < 3) {
                    std::cerr << "Command failed: " << command << std::endl;
                    return false; // Indicate failure
                } else {
                    std::cout << "Command executed successfully: " << command << std::endl;
                    return true; // Indicate success
                }
            });

            // Handle the result (success or failure) of the command execution
            if (result.get()) {
                // Successful execution, handle any follow-up actions
            } else {
                // Handle failed execution, e.g., retry logic, logging, alerts
            }
        }
    }
};

int main() {
    CommandExecutor executor;

    std::thread commandProcessor([&executor]() { executor.processCommands(); });

    // Simulate submitting commands asynchronously
    for (int i = 0; i < 10; ++i) {
        executor.executeCommand("Command " + std::to_string(i));
    }

    commandProcessor.join(); // Wait for the command processor thread to finish
    return 0;
}
