// C Function to Execute External Commands Asynchronously
void execute_external_command(char* command, int executor_id) {
    pthread_mutex_lock(&registry_lock); 

    CommandExecutorConfig* config = &command_executors[executor_id];
    config->execute_function(command);

    pthread_mutex_unlock(&registry_lock);
}



// C Function to Register a New Command Executor Factory
void register_command_executor_factory(int id, void (*execute_function)(char* command)) {
    pthread_mutex_lock(&registry_lock);
    command_executors = (CommandExecutorConfig*)realloc(command_executors, sizeof(CommandExecutorConfig) * (num_command_executors + 1));
    if (!command_executors) {
        fprintf(stderr, "Error allocating memory for command executor registry!\n");
        pthread_mutex_unlock(&registry_lock);
        return;
    }

    command_executors[num_command_executors].id = id; 
    command_executors[num_command_executors].execute_function = execute_function; 
    num_command_executors++;

    pthread_mutex_unlock(&registry_lock);
}



