NFAPI_CRC_INDICATION_PDU_T* allocate_and_manage_crc_indications(size_t N) {
    if (N > MAX_INDICATIONS) {
        // Log warning for exceeding limit
        fprintf(stderr, "Warning: Requesting %zu indications close to the system limit (%d).\n", N, MAX_INDICATIONS);
    }

    NFAPI_CRC_INDICATION_PDU_T* indications = NULL; 
    pthread_mutex_lock(&mutex);
    // Allocate memory for array (consider using a custom memory pool here)
    indications = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T)); 

    if (!indications) {
        // Log error and handle memory allocation failure
        fprintf(stderr, "Error: Failed to allocate memory for %zu indications.\n", N);
        pthread_mutex_unlock(&mutex);
        return NULL; 
    }

