#include <iostream>
#include <fstream>
#include <vector>
#include <map>
#include <cmath>

struct SensorData {
    int timestamp;
    double value;
};

class SensorAnalysis {
public:
    SensorAnalysis() {}
    std::map<int, std::pair<double, double>> analyze(const std::vector<SensorData>& data) {
        std::map<int, std::pair<double, double>> results;
        for (const auto& entry : data) {
            if (results.find(entry.timestamp) == results.end()) {
                results[entry.timestamp] = std::make_pair(0.0, 0);
            }
            results[entry.timestamp].first += entry.value;
            results[entry.timestamp].second++;
        }

        for (auto& it : results) {
            it.second.first /= it.second.second;
        }

        return results;
    }
};

int main() {
    std::ifstream file("sensor_data.bin", std::ios::binary);
    if (!file.is_open()) {
        std::cerr << "Error opening file." << std::endl;
        return 1;
    }

    std::vector<SensorData> data;
    while (file) {
        SensorData entry;
        file.read(reinterpret_cast<char*>(&entry.timestamp), sizeof(int));
        file.read(reinterpret_cast<char*>(&entry.value), sizeof(double));
        data.push_back(entry);
    }

    file.close();

    SensorAnalysis analyzer;
    auto results = analyzer.analyze(data);

    for (const auto& it : results) {
        std::cout << "Timestamp: " << it.first << ", Mean: " << it.second.first << std::endl;
    }

    return 0;
}
