#include <time.h>
#include "nfapi_crc_indication_pdu_t.h" // Assuming this header file exists

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdu;
    size_t count; 
} PDUBuffer;

pthread_mutex_t buffer_lock = PTHREAD_MUTEX_INITIALIZER;
PDUBuffer pdu_buffer;

void* process_pdu(void *arg) {
  while (1) {
    pthread_mutex_lock(&buffer_lock);
    if (pdu_buffer.count > 0) {
      NFAPI_CRC_INDICATION_PDU_T *pdu = pdu_buffer.pdu;
      pdu_buffer.count--;
      pdu_buffer.pdu++;

      // Process the PDU here, integrating with the external system
      pthread_mutex_unlock(&buffer_lock);
    } else {
      pthread_mutex_unlock(&buffer_lock);
      usleep(1000); // Yield to other threads
    }
  }
  return NULL;
}

void create_and_populate_crc_pdus(size_t num_pdus) {
  srand(time(NULL)); // Seed the random number generator
  pthread_mutex_lock(&buffer_lock);

  pdu_buffer.pdu = malloc(num_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T)); 
  if (!pdu_buffer.pdu) {
    // Handle memory allocation error
    pthread_mutex_unlock(&buffer_lock);
    return; 
  }

  for (size_t i = 0; i < num_pdus; i++) {
    NFAPI_CRC_INDICATION_PDU_T *pdu = &pdu_buffer.pdu[i];
    // Populate PDU fields: RX_UE_INFORMATION_TAG, RNTI, CRC_INDICATION_REL8_TAG with a random CRCFLAG

    pthread_mutex_unlock(&buffer_lock);

  }
  pthread_mutex_unlock(&buffer_lock); 


  // Create and start processing threads
  pthread_t threads[num_pdus];
  for (size_t i = 0; i < num_pdus; i++) {
    pthread_create(&threads[i], NULL, process_pdu, NULL);
  }

  // Wait for all threads to complete
  for (size_t i = 0; i < num_pdus; i++) {
    pthread_join(threads[i], NULL);
  }
}


