import java.util.concurrent.*;

public class TransactionProcessor {

    private final ExecutorService executor = Executors.newFixedThreadPool(10); // Adjust thread pool size as needed
    private final PaymentGatewayFactory gatewayFactory;
    private final Logger logger; 

    public TransactionProcessor(PaymentGatewayFactory gatewayFactory, Logger logger) {
        this.gatewayFactory = gatewayFactory;
        this.logger = logger;
    }

    public void processTransaction(Transaction transaction) {
        executor.submit(() -> {
            try {
                // Validate Transaction 
                if (!isValid(transaction)) {
                    logger.error("Invalid Transaction: {}", transaction);
                    return; // Handle invalid transactions appropriately
                }

                // Select Payment Gateway
                PaymentGateway gateway = gatewayFactory.selectGateway(transaction);

                // Process Transaction Asynchronously
                gateway.processTransactionAsync(transaction, new Callback() { 
                    @Override
                    public void onSuccess(TransactionResult result) {
                        logger.info("Transaction Successful: {}", transaction);
                        // Handle successful transactions
                    }

                    @Override
                    public void onFailure(Throwable error) {
                        logger.error("Transaction Failed: {} - Error: {}", transaction, error);
                        retryTransaction(transaction, error); // Retry on failure
                    }
                }); 
            } catch (Exception e) {
                logger.error("Unexpected Error processing Transaction: {} - Error: {}", transaction, e);
                // Handle unexpected errors appropriately
            }
        });
    }

    private boolean isValid(Transaction transaction) {
        // Implement transaction validation logic here
        return true; // Replace with actual validation
    }

    private void retryTransaction(Transaction transaction, Throwable error) {
        // Implement retry logic with exponential backoff and limited attempts
    }


} 



``` 


