public class SecureStringProcessor
{
    private readonly ILogger _logger;

    public SecureStringProcessor(ILogger logger)
    {
        _logger = logger;
    }

    public string GenerateMD5Hash(string input)
    {
        if (string.IsNullOrEmpty(input))
        {
            _logger.LogError("Invalid input: String is null or empty.");
            return null;
        }

        if (input.Length > 1000)
        {
            _logger.LogError("Invalid input: String exceeds maximum length of 1000 characters.");
            return null;
        }

        using (var md5 = MD5.Create())
        {
            var hashBytes = md5.ComputeHash(System.Text.Encoding.UTF8.GetBytes(input));
            return BitConverter.ToString(hashBytes).Replace("-", "");
        }
    }
}

