class Processor {
public:
    Processor(int numThreads) : numThreads_(numThreads) {
        for (int i = 0; i < numThreads_; ++i) {
            threads_.emplace_back([this]() { this->process(); });
        }
    }

    void addFile(const string& filePath) {
        ifstream file(filePath);
        if (file.is_open()) {
            string line;
            while (getline(file, line)) {
                queue_.push({line, 0}); // Initialize average to 0
            }
            file.close();
        } else {
            cerr << "Error opening file: " << filePath << endl;
        }
    }

