struct Command {
    std::string payload;
};

class CommandExecutor {
private:
    std::queue<Command> commandQueue;
    std::mutex queueMutex;
    std::condition_variable cv;

public:
    void enqueueCommand(const Command& cmd) {
        std::unique_lock<std::mutex> lock(queueMutex);
        commandQueue.push(cmd);
        cv.notify_one(); 
    }

    void processCommands() {
        while (true) {
            std::unique_lock<std::mutex> lock(queueMutex);
            cv.wait(lock, [this]{ return !commandQueue.empty(); });
            Command cmd = commandQueue.front();
            commandQueue.pop();
            lock.unlock();

            // Execute the command (replace with actual execution logic)
            std::cout << "Executing command: " << cmd.payload << std::endl; 
        }
    }
};

int main() {
    CommandExecutor executor;
    std::thread processingThread(&CommandExecutor::processCommands, &executor);

    // Enqueue commands
    executor.enqueueCommand({ "command1" });
    executor.enqueueCommand({ "command2" });

    processingThread.join(); 
    return 0;
}
