#include <condition_variable>

class SensorDataProcessor {
public:
    SensorDataProcessor(int maxQueueSize) : dataQueue(maxQueueSize) {}

    void processData(const std::string& sensorData) {
        std::unique_lock<std::mutex> lock(dataMutex);
        dataQueue.push(sensorData);
        cv.notify_one(); 
    }

    void startWorkerThreads() {
        for (int i = 0; i < workerCount; ++i) {
            workers.emplace_back([this] { processIncomingData(); });
        }
    }

private:
    void processIncomingData() {
        while (true) {
            std::unique_lock<std::mutex> lock(dataMutex);
            cv.wait(lock, [this] { return !dataQueue.empty(); });

            std::string data = dataQueue.front();
            dataQueue.pop(); 
            lock.unlock();

            // Process sensorData here
            std::cout << "Processing: " << data << std::endl; 
        }
    }

    std::queue<std::string> dataQueue;
    std::mutex dataMutex;
    std::condition_variable cv;
    int workerCount = 4; // Adjust based on your hardware
};

int main() {
    SensorDataProcessor processor(1000);
    processor.startWorkerThreads();

    // Simulate incoming sensor data
    for (int i = 0; i < 10000; ++i) {
        processor.processData("Sensor Data " + std::to_string(i));
    }

    return 0;
}
